cliff-stair.source:
const flights = Math.max(1, Math.round(params.flights));
const steps = Math.max(8, Math.round(params.steps));
const rise = params.rise, run = params.run, W = params.width, LD = params.landing, th = params.thickness, base = params.base;
const riser = rise / steps;
const L = steps * run;
const totalZ = 2 * W + 0.6;
const zA = -(W / 2 + 0.3);
const zB = W / 2 + 0.3;
const halfX = L / 2 + LD;
const DEG = 180 / Math.PI;
const M = [];
const T = [];
function bx(list, w, h, d, x, y, z, rz, ry) {
  let b = api.box(w, h, d);
  if (rz) b = b.rotate(0, 0, rz);
  if (ry) b = b.rotate(0, ry, 0);
  list.push(b.translate(x, y, z));
}
function col(hx, hy, hz, x, y, z, rz, ry) {
  const c = { kind: 'box', halfExtents: [hx, hy, hz], offset: [x, y, z] };
  if (rz || ry) c.rotation = [0, ry || 0, rz || 0];
  api.collider(c);
}
function landing(xc, y, solid) {
  const t = solid ? y : 0.8;
  bx(M, LD, t, totalZ, xc, y - t / 2, 0);
  col(LD / 2, t / 2, totalZ / 2, xc, y - t / 2, 0);
}
function hrail(x1, z1, x2, z2, y) {
  const dx = x2 - x1, dz = z2 - z1;
  const len = Math.sqrt(dx * dx + dz * dz);
  const yaw = Math.atan2(-dz, dx) * DEG;
  const cx = (x1 + x2) / 2, cz = (z1 + z2) / 2;
  bx(T, len, 0.14, 0.22, cx, y + 1.0, cz, 0, yaw);
  bx(T, len, 0.2, 0.3, cx, y + 0.1, cz, 0, yaw);
  const n = Math.max(1, Math.round(len / 0.8));
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const px = x1 + dx * t, pz = z1 + dz * t;
    if (i === 0 || i === n || i % 6 === 0) bx(T, 0.24, 1.2, 0.24, px, y + 0.6, pz);
    else bx(T, 0.1, 0.9, 0.1, px, y + 0.5, pz);
  }
  col(len / 2, 0.55, 0.08, cx, y + 0.55, cz, 0, yaw);
}
function srail(dir, sx, y0, zEdge) {
  const ang = Math.atan2(rise, L) * DEG;
  const len = Math.sqrt(L * L + rise * rise);
  const xm = sx + dir * L / 2;
  const ym = y0 + rise / 2 + riser / 2;
  const rz = dir * ang;
  bx(T, len, 0.14, 0.22, xm, ym + 1.0, zEdge, rz);
  bx(T, len, 0.2, 0.3, xm, ym + 0.1, zEdge, rz);
  const n = Math.max(2, Math.round(len / 0.8));
  for (let i = 0; i <= n; i++) {
    const xl = L * i / n;
    const px = sx + dir * xl;
    const ly = y0 + riser * xl / run + riser / 2;
    if (i === 0 || i === n || i % 6 === 0) bx(T, 0.24, 1.2, 0.24, px, ly + 0.6, zEdge);
    else bx(T, 0.1, 0.9, 0.1, px, ly + 0.5, zEdge);
  }
  col(len / 2, 0.55, 0.08, xm, ym + 0.6, zEdge, rz);
}
let maxR = 0, maxL = base;
landing(-(L / 2 + LD / 2), base, true);
for (let f = 0; f < flights; f++) {
  const dir = f % 2 === 0 ? 1 : -1;
  const zc = f % 2 === 0 ? zA : zB;
  const y0 = base + f * rise;
  const sx = dir > 0 ? -L / 2 : L / 2;
  const h = riser + th;
  for (let k = 0; k < steps; k++) {
    const x = sx + dir * (k + 0.5) * run;
    const yt = y0 + (k + 1) * riser;
    bx(M, run + 0.01, h, W, x, yt - h / 2, zc);
  }
  const ang = Math.atan2(rise, L) * DEG;
  const len = Math.sqrt(L * L + rise * rise);
  col(len / 2 + 0.05, 0.3, W / 2, sx + dir * L / 2, y0 + rise / 2 + 0.1 - 0.3, zc, dir * ang);
  srail(dir, sx, y0, zc - (W / 2 - 0.11));
  srail(dir, sx, y0, zc + (W / 2 - 0.11));
  const ly = y0 + rise;
  landing(dir * (L / 2 + LD / 2), ly, false);
  const xo = dir * (halfX - 0.11);
  hrail(xo, -totalZ / 2 + 0.11, xo, totalZ / 2 - 0.11, ly);
  hrail(dir * (L / 2), totalZ / 2 - 0.11, xo, totalZ / 2 - 0.11, ly);
  if (dir > 0) maxR = Math.max(maxR, ly); else maxL = Math.max(maxL, ly);
}
for (const s of [-1, 1]) {
  const top = (s > 0 ? maxR : maxL) - 0.8;
  if (top <= 0.5) continue;
  for (const zz of [-1, 1]) {
    const x = s * (halfX - 0.7), z = zz * (totalZ / 2 - 0.7);
    bx(M, 1, top, 1, x, top / 2, z);
    col(0.5, top / 2, 0.5, x, top / 2, z);
  }
}
function combine(list) {
  let m = list[0];
  for (let i = 1; i < list.length; i++) m.merge(list[i]);
  return m;
}
api.add(combine(M), { preset: 'stone', finish: 'marble', color: params.color, roughness: 0.35 });
api.add(combine(T), { preset: 'stone', finish: 'marble', color: params.trimColor, roughness: 0.4 });
return api.build();

cliff-stair-grand.source:
const PITCH=2.6,XS=18,RUN=36,RISE=9,NST=50,SR=RUN/NST,SH=RISE/NST,SL=RISE/RUN,BASE=1,N=5;
const TH=Math.atan(SL)*180/Math.PI,LL=Math.sqrt(RUN*RUN+RISE*RISE),SN=Math.sin(Math.atan(SL)),CS=Math.cos(Math.atan(SL));
const mTread={finish:'marble',color:'#e6dec9',roughness:0.78,surface:{layers:[{kind:'tone',amount:0.35},{kind:'grime',amount:0.25},{kind:'edgeWear',amount:0.35},{kind:'moss',amount:0.2,mask:{noise:0.35}}]}};
const mTrim={finish:'marble',color:'#f5eedd',roughness:0.5,surface:{layers:[{kind:'veins',amount:0.3},{kind:'edgeWear',amount:0.3}]}};
const mGold={preset:'gold',color:'#c9a24a',metalness:0.8,roughness:0.35};
const mBronze={preset:'metal',color:'#4a3a2a',metalness:0.6,roughness:0.5};
const mass=[],trim=[],gold=[],bronze=[];
const zc=i=>5.2-PITCH*i,y0=i=>BASE+RISE*i,dirOf=i=>(i%2===0?1:-1),yl=(i,u)=>y0(i)+0.09+SL*u,xs=i=>-dirOf(i)*XS;
const toX=(i,pts)=>{const d=dirOf(i),s=xs(i);const r=pts.map(p=>[s+d*p[0],p[1]]);if(d<0)r.reverse();return r;};
const urnAt=(x,y,z,s)=>{trim.push(api.lathe([[0.001,0],[0.2,0],[0.22,0.05],[0.14,0.14],[0.3,0.42],[0.34,0.6],[0.26,0.78],[0.15,0.86],[0.25,0.94],[0.25,1.0],[0.001,1.0]],12).scale(s).translate(x,y,z));};
const newel=(x,y,z,urn)=>{trim.push(api.roundedBox(0.55,1.4,0.55,0.04,1).translate(x,y+0.55,z));trim.push(api.roundedBox(0.7,0.1,0.7,0.03,1).translate(x,y+1.3,z));if(urn){urnAt(x,y+1.35,z,0.9);}else{trim.push(api.sphere(0.19,1).translate(x,y+1.52,z));}};
const BANDS=[[0.3,0.22,0.17],[1.5,0.14,0.07],[3,0.14,0.07],[4.5,0.14,0.07],[6,0.14,0.07],[7.5,0.14,0.07],[9,0.14,0.07],[10.5,0.14,0.07],[12,0.14,0.07],[13.5,0.14,0.07],[15,0.14,0.07],[16.5,0.14,0.07]];
for(let i=0;i<N;i++){
const d=dirOf(i),z=zc(i);
const pts=[[0,0],[RUN,0],[RUN,y0(i)+RISE]];
for(let k=NST-1;k>=0;k--){pts.push([k*SR,y0(i)+(k+1)*SH]);if(k>0)pts.push([k*SR,y0(i)+k*SH]);}
mass.push(api.extrude(toX(i,pts),PITCH).translate(0,0,z));
const pP=[[0,yl(i,0)-0.25],[RUN,yl(i,RUN)-0.25],[RUN,yl(i,RUN)+0.95],[0,yl(i,0)+0.95]];
const pC=[[-0.2,yl(i,-0.2)+0.95],[RUN+0.2,yl(i,RUN+0.2)+0.95],[RUN+0.2,yl(i,RUN+0.2)+1.07],[-0.2,yl(i,-0.2)+1.07]];
trim.push(api.extrude(toX(i,pP),0.4).translate(0,0,z+1.1));
trim.push(api.extrude(toX(i,pC),0.54).translate(0,0,z+1.1));
if(i===N-1){trim.push(api.extrude(toX(i,pP),0.4).translate(0,0,z-1.1));trim.push(api.extrude(toX(i,pC),0.54).translate(0,0,z-1.1));}
for(let j=0;j<=6;j++){const u=j*6;newel(xs(i)+d*u,yl(i,u),z+1.1,false);}
for(let j=0;j<6;j++){const u=3+6*j;const x=xs(i)+d*u,y=yl(i,u)+0.5;gold.push(api.cylinder(0.26,0.26,0.05,16).rotate(90,0,0).translate(x,y,z+1.325));bronze.push(api.torus(0.3,0.035).translate(x,y,z+1.33));}
for(const b of BANDS){const dd=b[0];const u0=Math.max(0,(dd+0.35-y0(i)-0.09)/SL);if(u0>=RUN-1)continue;const yb0=yl(i,u0)-dd,yb1=yl(i,RUN)-dd;trim.push(api.extrude(toX(i,[[u0,yb0],[RUN,yb1],[RUN,yb1+b[1]],[u0,yb0+b[1]]]),b[2]).translate(0,0,z+1.3+b[2]/2));}
const ym=yl(i,RUN/2);
api.collider({kind:'box',halfExtents:[LL/2+0.1,0.3,1.3],offset:[0.3*d*SN,ym-0.3*CS,z],rotation:[0,0,d*TH]});
api.collider({kind:'box',halfExtents:[LL/2,0.5,0.2],offset:[-0.5*d*SN,ym+0.5*CS,z+1.1],rotation:[0,0,d*TH]});
if(i===N-1){api.collider({kind:'box',halfExtents:[LL/2,0.5,0.2],offset:[-0.5*d*SN,ym+0.5*CS,z-1.1],rotation:[0,0,d*TH]});}
}
const L=[[1,0,1],[-1,1,2],[1,2,3],[-1,3,4],[1,4,4]];
for(const e of L){
const sd=e[0],a=e[1],b=e[2];const top=y0(a)+RISE;
const zF=zc(a)+1.3,zB=zc(b)-1.3,dep=zF-zB,zm=(zF+zB)/2,xc=sd*(XS+1.5);
mass.push(api.box(3,top-0.2,dep).translate(xc,(top-0.2)/2,zm));
trim.push(api.roundedBox(3.1,0.2,dep+0.1,0.04,1).translate(xc,top-0.1,zm));
trim.push(api.box(3,0.95,0.4).translate(xc,top+0.475,zF-0.2));
trim.push(api.roundedBox(3.1,0.12,0.54,0.03,1).translate(xc,top+1.01,zF-0.2));
trim.push(api.box(0.4,0.95,dep).translate(sd*(XS+2.8),top+0.475,zm));
trim.push(api.roundedBox(0.54,0.12,dep+0.1,0.03,1).translate(sd*(XS+2.8),top+1.01,zm));
newel(sd*(XS+2.75),top,zF-0.25,true);
api.collider({kind:'box',halfExtents:[1.5,top/2,dep/2],offset:[xc,top/2,zm]});
api.collider({kind:'box',halfExtents:[0.2,0.5,dep/2],offset:[sd*(XS+2.8),top+0.5,zm]});
api.collider({kind:'box',halfExtents:[1.5,0.5,0.2],offset:[xc,top+0.5,zF-0.2]});
if(b===4&&sd<0){
trim.push(api.box(3,0.95,0.4).translate(xc,top+0.475,zB+0.2));
trim.push(api.roundedBox(3.1,0.12,0.54,0.03,1).translate(xc,top+1.01,zB+0.2));
newel(sd*(XS+2.75),top,zB+0.25,true);
api.collider({kind:'box',halfExtents:[1.5,0.5,0.2],offset:[xc,top+0.5,zB+0.2]});
}
for(let h=1.6;h<top-0.5;h+=1.8){trim.push(api.box(3.0,0.12,0.07).translate(xc,h,zF+0.035));trim.push(api.box(0.07,0.12,dep).translate(sd*(XS+3.035),h,zm));}
}
const mg=a=>{const r=a[0];for(let i=1;i<a.length;i++)r.merge(a[i]);return r;};
api.add(mg(mass),mTread);api.add(mg(trim),mTrim);api.add(mg(gold),mGold);api.add(mg(bronze),mBronze);
return api.build();

cliff-stair-masonry.source:
const W=2.6,HW=1.3,N=52,XL=-13,XR=13,RUN=26,RISE=8.8,T=RUN/N,R=RISE/N,S=RISE/RUN;
const marble={preset:'stone',finish:'marble',color:'#f5eedd',roughness:0.5,surface:{layers:[{kind:'tone',amount:0.35},{kind:'streaks',amount:0.3},{kind:'edgeWear',amount:0.4},{kind:'moss',amount:0.2,mask:{noise:0.5}}]}};
const ashlar={preset:'stone',finish:'stone',color:'#e4d9c0',roughness:0.85,surface:{layers:[{kind:'tone',amount:0.5},{kind:'grime',amount:0.45},{kind:'lichen',amount:0.3},{kind:'moss',amount:0.3,mask:{noise:0.5}}]}};
function put(m,mat,amt){m.vertexColor((x,y,z)=>{const n=0.5+0.5*api.noise3(x*0.35,y*0.35,z*0.35);const g=Math.max(0,1-y/6)*0.25;return api.mix('#ffffff','#d9c9a4',Math.min(1,Math.max(0,n*amt+g)));});api.add(m,mat);}
function poly(ylow){const pts=[[XL,0],[XR,0]];for(let i=N-1;i>=0;i--){const h=ylow+(i+1)*R;pts.push([XL+(i+1)*T,h]);pts.push([XL+i*T,h]);}return pts;}
const ang=Math.atan(S)*180/Math.PI;const len=RUN/Math.cos(Math.atan(S));
function urn(x,y,z){const u=api.lathe([[0,0],[0.16,0],[0.2,0.05],[0.12,0.12],[0.18,0.28],[0.24,0.42],[0.2,0.54],[0.24,0.58],[0,0.58]],16);u.translate(x,y,z);put(u,marble,0.4);}
for(let k=0;k<5;k++){
 const ylow=1+RISE*k,yhigh=ylow+RISE,dir=(k%2===0)?1:-1,zc=5.2-2.6*k;
 const fm=api.extrude(poly(ylow),W);if(dir<0)fm.rotate(0,180,0);fm.translate(0,0,zc);put(fm,marble,0.5);
 const pts=[];for(const z of [zc-HW,zc+HW]){for(const x of [XL,XR]){const yt=dir>0?ylow+R-0.09+(x-XL)*S:ylow+R-0.09+(XR-x)*S;pts.push(x,0,z,x,yt,z);}}
 api.collider({kind:'hull',points:pts,offset:[0,0,0]});
 const zf=zc+HW-0.15,y0=ylow+R-0.15;
 const wall=api.extrude([[XL,y0],[XR,y0+RISE],[XR,y0+RISE+0.95],[XL,y0+0.95]],0.3);
 const cop=api.extrude([[XL,y0+0.95],[XR,y0+RISE+0.95],[XR,y0+RISE+1.09],[XL,y0+1.09]],0.46);
 for(const m of [wall,cop]){if(dir<0)m.rotate(0,180,0);m.translate(0,0,zf);put(m,marble,0.4);}
 api.collider({kind:'box',halfExtents:[len/2,0.48,0.15],offset:[0,y0+RISE/2+0.475,zf],rotation:[0,0,ang*dir]});
 const ends=[{x:dir>0?XL+0.25:XR-0.25,y:ylow},{x:dir>0?XR-0.25:XL+0.25,y:yhigh}];
 for(const e of ends){const n=api.box(0.5,1.3,0.5).translate(e.x,e.y+0.6,zf);put(n,marble,0.4);urn(e.x,e.y+1.25,zf);}
}
function landing(xa,xb,za,zb,top){const w=xb-xa,d=zb-za,cx=(xa+xb)/2,cz=(za+zb)/2;
 put(api.box(w,Math.max(0.2,top-0.3),d).translate(cx,Math.max(0.2,top-0.3)/2,cz),ashlar,0.6);
 put(api.box(w,0.3,d).translate(cx,top-0.15,cz),marble,0.4);
 for(let y=3.6;y<top-0.6;y+=3.6){put(api.box(w+0.2,0.18,d+0.2).translate(cx,y,cz),marble,0.4);}
 put(api.box(w+0.2,0.35,d+0.2).translate(cx,0.17,cz),ashlar,0.6);
 api.collider({kind:'box',halfExtents:[w/2,top/2,d/2],offset:[cx,top/2,cz]});}
function pX(xa,xb,z,yb){const cx=(xa+xb)/2,w=xb-xa;put(api.box(w,0.95,0.3).translate(cx,yb+0.475,z),marble,0.4);put(api.box(w,0.14,0.46).translate(cx,yb+1.02,z),marble,0.4);api.collider({kind:'box',halfExtents:[w/2,0.5,0.15],offset:[cx,yb+0.5,z]});}
function pZ(x,za,zb,yb){const cz=(za+zb)/2,d=zb-za;put(api.box(0.3,0.95,d).translate(x,yb+0.475,cz),marble,0.4);put(api.box(0.46,0.14,d).translate(x,yb+1.02,cz),marble,0.4);api.collider({kind:'box',halfExtents:[0.15,0.5,d/2],offset:[x,yb+0.5,cz]});}
const Ls=[
 {xa:-21,xb:-13,za:3.9,zb:6.5,top:1,fz:6.35,ez:-20.85},
 {xa:13,xb:21,za:1.3,zb:6.5,top:9.8,fz:6.35,ez:20.85},
 {xa:-21,xb:-13,za:-1.3,zb:3.9,top:18.6,fz:3.75,ez:-20.85},
 {xa:13,xb:21,za:-3.9,zb:1.3,top:27.4,fz:1.15,ez:20.85},
 {xa:-21,xb:-13,za:-6.5,zb:-1.3,top:36.2,fz:-1.45,ez:-20.85},
 {xa:13,xb:21,za:-6.5,zb:-3.9,top:45,fz:-4.05,ez:20.85}];
for(const L of Ls){landing(L.xa,L.xb,L.za,L.zb,L.top);pX(L.xa,L.xb,L.fz,L.top);pZ(L.ez,L.za,L.zb,L.top);}
return api.build();

cliff-stair-treads.source:
const STONE={finish:'stone',color:'#e8dfc8',roughness:0.9};
const MARBLE={finish:'marble',color:'#f4eddc',roughness:0.5};
const HONEY={finish:'marble',color:'#e6d3a8',roughness:0.6};
const GOLD={preset:'gold',color:'#c9a24a',roughness:0.35,metalness:0.8};
const LH=3,X0=-18,X1=18,RISE=9,N=50,H0=1,LAND=3.5;
const run=(X1-X0)/N,rise=RISE/N;
const flip=(pts)=>pts.map((p)=>[-p[0],p[1]]).reverse();
const urn=[[0.001,0],[0.16,0],[0.2,0.08],[0.3,0.32],[0.27,0.52],[0.17,0.6],[0.22,0.68],[0.26,0.74],[0.001,0.74]];
for(let k=0;k<5;k++){
const west=(k%2===0);
const hs=H0+RISE*k;
const zc=(2-k)*LH;
const zS=zc+LH/2;
const ly=(x)=>west?hs+RISE*(x-X0)/(X1-X0):hs+RISE*(X1-x)/(X1-X0);
let pts=[[X0,0],[X1,0]];
for(let i=N-1;i>=0;i--){const y=hs+rise*(i+1);pts.push([X0+(i+1)*run,y]);pts.push([X0+i*run,y]);}
if(!west)pts=flip(pts);
api.add(api.extrude(pts,LH).translate(0,0,zc),STONE);
const xa=west?X0:X1,xb=west?X1:X0;
const hp=[];
for(const z of [zc-LH/2,zc+LH/2]){hp.push(xa,0,z,xb,0,z,xb,hs+RISE,z,xa,hs,z);}
api.collider({kind:'hull',points:hp,offset:[0,0,0]});
let pp=[[X0,hs],[X1,hs+RISE],[X1,hs+RISE+1],[X0,hs+1]];
if(!west)pp=flip(pp);
api.add(api.extrude(pp,0.35).translate(0,0,zS-0.175),MARBLE);
let cp=[[X0,hs+1],[X1,hs+RISE+1],[X1,hs+RISE+1.12],[X0,hs+1.12]];
if(!west)cp=flip(cp);
api.add(api.extrude(cp,0.45).translate(0,0,zS-0.225),HONEY);
for(let j=0;j<=8;j++){const x=X0+4.5*j;api.add(api.roundedBox(0.5,1.5,0.5,0.05).translate(x,ly(x)+0.65,zS-0.175),MARBLE);}
if(k>0){for(const x of [-9,0,9]){const y=ly(x)-3;api.add(api.cylinder(0.9,0.9,0.1,28).rotate(90,0,0).translate(x,y,zS+0.03),GOLD);api.add(api.torus(1.05,0.09).translate(x,y,zS+0.05),MARBLE);}}
const endX=west?X1:X0;
const dir=west?1:-1;
const top=hs+RISE;
const last=(k===4);
const d=last?LH:2*LH;
const zl=last?zc:zc-LH/2;
const xl=endX+dir*LAND/2;
api.add(api.box(LAND,top,d).translate(xl,top/2,zl),STONE);
api.collider({kind:'box',halfExtents:[LAND/2,top/2,d/2],offset:[xl,top/2,zl]});
api.add(api.box(0.35,1,d).translate(endX+dir*(LAND-0.175),top+0.5,zl),MARBLE);
api.add(api.box(0.5,0.12,d).translate(endX+dir*(LAND-0.25),top+1.06,zl),HONEY);
const cx=endX+dir*(LAND-0.35)/2;
api.add(api.box(LAND-0.35,1,0.35).translate(cx,top+0.5,zl+d/2-0.175),MARBLE);
