var W=params.width, D=params.depth, F=Math.max(1,Math.round(params.floors));
var fh=3.1, base=0.5, H=F*fh, topY=base+H, ov=0.55, rnd=api.rng;
var acc={};
function put(k,m,mat){ if(acc[k]){acc[k].mesh.merge(m);} else {acc[k]={mesh:m,mat:mat};} }
