bx('trim',trimMat,W+0.7,0.1,D+0.7,0,topY+0.27,0);
for(var dx=-W/2+0.2;dx<W/2;dx+=0.36){ bx('trim',trimMat,0.17,0.13,0.14,dx,topY-0.09,D/2+0.1); bx('trim',trimMat,0.17,0.13,0.14,dx,topY-0.09,-D/2-0.1); }
for(var dz=-D/2+0.2;dz<D/2;dz+=0.36){ bx('trim',trimMat,0.14,0.13,0.17,W/2+0.1,topY-0.09,dz); bx('trim',trimMat,0.14,0.13,0.17,-W/2-0.1,topY-0.09,dz); }
var n=Math.max(3,2*Math.floor(W/4.4)+1), mid=(n-1)/2;
var ns=Math.max(1,Math.round(D/3.6));
for(var f=0;f<F;f++){
  for(var i=0;i<n;i++){
    var xc=-W/2+(i+0.5)*W/n;
    if(i===mid && f===0){ }
    else if(i===mid && f>=1 && params.balcony){ win(f,xc,D/2,0,1,0,true); balcony(f,xc); }
    else { win(f,xc,D/2,0,1,0,false); }
    win(f,xc,-D/2,0,-1,0,false);
  }
  for(var j=0;j<ns;j++){
    var zc=-D/2+(j+0.5)*D/ns;
    win(f,W/2,zc,1,0,0,false);
    win(f,-W/2,zc,-1,0,0,false);
  }
}
part('door',doorMat,1.1,2.0,0.08,0,D/2,0,1,0,base+1.0,0.02);
arch('door',doorMat,0.55,0.08,0,D/2,0,1,0,base+2.0,0.02);
part('trim',trimMat,0.24,2.6,0.2,0,D/2,0,1,-0.82,base+1.3,0.08);
part('trim',trimMat,0.24,2.6,0.2,0,D/2,0,1,0.82,base+1.3,0.08);
part('trim',trimMat,2.1,0.14,0.55,0,D/2,0,1,0,base+2.72,0.27);
bx('step',stepMat,2.4,0.25,0.6,0,0.125,D/2+0.55);
bx('step',stepMat,2.2,0.5,0.6,0,0.25,D/2+0.35);
put('lamp',api.sphere(0.12).translate(1.3,base+2.1,D/2+0.15),lampMat);
var rt=topY+0.3, ph, chx, chz;
if(params.variant===0){
  var span=D+2*ov, L=W+2*ov; ph=span/2*0.36;
