const W=params.width,L=params.length,H=params.height,N=Math.max(4,Math.round(params.columns));
const marble={preset:'stone',finish:'marble',color:params.color,roughness:0.5,surface:{layers:[{kind:'veins',amount:0.35},{kind:'tone',amount:0.3},{kind:'edgeWear',amount:0.35},{kind:'streaks',amount:0.25}]}};
