const dark={preset:'stone',color:'#2b2622',roughness:0.95};
function stain(m,k){m.vertexColor((x,y,z)=>{const f=Math.max(0,Math.min(1,k*(0.35+0.65*(0.5+0.5*api.noise3(x*0.5,y*0.5,z*0.5)))));return api.mix('#ffffff','#e0c48c',f);});return m;}
function put(m,mat){api.add(m,mat);}
function bx(w,h,d,x,y,z,mat,r){const m=r?api.roundedBox(w,h,d,r,2):api.box(w,h,d);m.translate(x,y,z);put(m,mat);}
const ex=W/2-1.2,ez=L/2-1.2,M=2*N+1,dx=2*ex/(N-1),dz=2*ez/(M-1),y0=0.9,yA=y0+H;
for(let i=0;i<3;i++){const inf=(3-i)*0.6;const w=W+2*inf,d=L+2*inf;const m=api.roundedBox(w,0.3,d,0.03,2).translate(0,0.15+i*0.3,0);stain(m,0.55);put(m,marble);api.collider({kind:'box',halfExtents:[w/2,0.15*(i+1),d/2],offset:[0,0.15*(i+1),0]});}
api.collider({kind:'hull',points:[-3.5,0,L/2+1.8,3.5,0,L/2+1.8,-3.5,0.3,L/2+1.8,3.5,0.3,L/2+1.8,-3.5,0.9,L/2+0.6,3.5,0.9,L/2+0.6,-3.5,0,L/2+0.6,3.5,0,L/2+0.6],offset:[0,0,0]});
const r=H*0.052,hs=H-0.67;
const prof=[[0.01,0],[r*1.04,0],[r*1.02,0.05]];
for(let i=0;i<=10;i++){const t=i/10;prof.push([r*(1-0.2*t)+r*0.03*Math.sin(Math.PI*t),0.05+t*(hs-0.05)]);}
prof.push([r*0.76,hs+0.03],[r*0.84,hs+0.06],[r*1.0,hs+0.16],[r*1.2,hs+0.3],[r*1.22,hs+0.32],[0.01,hs+0.32]);
const tmpl=api.lathe(prof,48);
tmpl.displace((x,y,z)=>(y>0.08&&y<hs)?-0.035*(0.5+0.5*Math.cos(16*Math.atan2(z,x))):0);
tmpl.merge(api.box(r*2.6,0.35,r*2.6).translate(0,H-0.175,0));
const pos=[];
for(let i=0;i<N;i++){const x=-ex+i*dx;pos.push([x,-ez],[x,ez]);}
for(let j=1;j<M-1;j++){const z=-ez+j*dz;pos.push([-ex,z],[ex,z]);}
let cols=null;
for(const p of pos){const c=tmpl.clone().translate(p[0],y0,p[1]);cols=cols?cols.merge(c):c;api.collider({kind:'cylinder',halfHeight:H/2,radius:r,offset:[p[0],y0+H/2,p[1]]});}
cols.vertexColor((x,y,z)=>{const h=y-y0;const f=Math.max(0,Math.min(1,Math.max(0,1-h/1.8)*0.5+(h>H-0.9?0.3:0)+0.2*(0.5+0.5*api.noise3(x*0.6,y*0.3,z*0.6))));return api.mix('#ffffff','#dcbd85',f);});
