for(const s of [-1,1]){
 bx(2*ex+1.3,0.9,1.3,0,yA+0.45,s*ez,marble,0.04);
 bx(1.3,0.9,2*ez+1.3,s*ex,yA+0.45,0,marble,0.04);
 bx(2*ex+1.0,1.1,1.0,0,yA+1.45,s*ez,metope);
 bx(1.0,1.1,2*ez+1.0,s*ex,yA+1.45,0,metope);
 bx(2*ex+1.3,0.1,0.05,0,yA+0.8,s*(ez+0.67),gold);
 bx(0.05,0.1,2*ez+1.3,s*(ex+0.67),yA+0.8,0,gold);
 bx(2*ex+2.6,0.35,2.2,0,yA+2.175,s*(ez+0.3),marble,0.04);
 bx(2.2,0.35,2*ez+2.6,s*(ex+0.3),yA+2.175,0,marble,0.04);
}
const fy=yA+1.45;
for(const s of [-1,1]){
 for(let i=0;i<N;i++){const x=-ex+i*dx;bx(0.5,1.1,0.14,x,fy,s*(ez+0.57),marble);if(i<N-1)bx(0.5,1.1,0.14,x+dx/2,fy,s*(ez+0.57),marble);}
 for(let j=0;j<M;j++){const z=-ez+j*dz;bx(0.14,1.1,0.5,s*(ex+0.57),fy,z,marble);if(j<M-1)bx(0.14,1.1,0.5,s*(ex+0.57),fy,z+dz/2,marble);}
}
const yb=yA+2.35,hp=ex+1.0,rp=hp*0.2,ang=Math.atan(rp/hp)*180/Math.PI,rl=Math.sqrt(hp*hp+rp*rp);
for(const s of [-1,1]){
 const tm=api.extrude([[-hp,0],[hp,0],[0,rp]],0.6);tm.translate(0,yb,s*(ez+0.3));put(tm,metope);
 for(const sd of [-1,1]){const rk=api.roundedBox(rl+0.3,0.35,0.9,0.03,2).rotate(0,0,sd>0?-ang:ang).translate(sd*hp/2,yb+rp/2+0.1,s*(ez+1.0));put(rk,marble);}
 const zf=s*(ez+0.72);
 for(let k=-4;k<=4;k++){
  const x=k*hp*0.19;const a=Math.abs(k);
  if(a<=2){const fh=1.6-0.25*a;put(api.capsule(0.2,fh).translate(x,yb+fh/2+0.05,zf),marble);put(api.sphere(0.15,2).translate(x,yb+fh+0.18,zf),marble);}
  else{const len=a===3?1.3:1.0;put(api.capsule(0.17,len).rotate(0,0,90).translate(x,yb+0.3,zf),marble);put(api.sphere(0.13,2).translate(x+(k<0?-len*0.5:len*0.5),yb+0.42,zf),marble);}
 }
 put(api.cone(0.4,1.4,6).scale(1.6,1,0.35).translate(0,yb+rp+0.75,s*(ez+0.8)),gold);
 for(const sd of [-1,1])put(api.cone(0.3,0.95,6).scale(1.4,1,0.35).translate(sd*(hp-0.2),yb+0.55,s*(ez+0.8)),gold);
}
const wr=hp+0.2,rr=wr*0.2,rang=Math.atan(0.2)*180/Math.PI,rlen=Math.sqrt(wr*wr+rr*rr)+0.2,Lr=2*(ez+1.45);
for(const sd of [-1,1]){
 const sl=api.roundedBox(rlen,0.28,Lr,0.03,2).rotate(0,0,sd>0?-rang:rang).translate(sd*wr/2,yb+rr/2+0.16,0);put(sl,roofMat);
 const nz=Math.floor(Lr/0.55);let ribs=null;
 for(let k=0;k<nz;k++){const z=-Lr/2+0.3+k*0.55;const rb=api.box(rlen-0.3,0.08,0.14).rotate(0,0,sd>0?-rang:rang).translate(sd*wr/2,yb+rr/2+0.34,z);ribs=ribs?ribs.merge(rb):rb;}
 put(ribs,roofMat);
}
put(api.roundedBox(0.6,0.3,Lr,0.05,2).translate(0,yb+rr+0.32,0),roofMat);
