for(const s of [-1,1]){bx(wt,hw,zlen+wt,s*cwh,y0+hw/2,zm,ashlar);bx(0.9,hw-0.4,0.5,s*(cwh+wt/2-0.45),y0+(hw-0.4)/2,zf2+wt/2+0.25,marble,0.03);bx(0.9,hw-0.4,0.5,s*(cwh+wt/2-0.45),y0+(hw-0.4)/2,zb-wt/2-0.25,marble,0.03);}
