const ashM={finish:'limestone',color:'#ffffff',roughness:0.85};
const bronzeM={preset:'metal',finish:'brass',color:'#6b4a22',metalness:0.75,roughness:0.45};
const goldM={preset:'metal',finish:'brass',color:'#d4a93a',metalness:0.8,roughness:0.35};
const flameM={preset:'emissive',color:'#ff7a1a',emissive:'#ff7a1a',emissiveIntensity:4};
const bannerM={preset:'fabric',finish:'fabric',color:'#1d3463',roughness:0.9,doubleSided:true};
function stain(x,y,z,edge,crev){
  const n=api.noise3(x*0.5,y*0.8,z*0.5);
  const vein=clamp(1-Math.abs(n)/0.09,0,1);
  let c=api.mix(C,VEIN,0.5*vein);
  const hn=0.5+0.5*api.noise3(x*0.35+3,y*0.3,z*0.35);
  const h=clamp(edge*0.7+0.25*hn-0.05,0,0.85);
  c=api.mix(c,H,h);
  if(y<5){const m=clamp((api.noise3(x*0.9+9,y*1.3,z*0.9)-0.25)*2.0,0,1)*(1-y/5)*0.65;if(m>0.01)c=api.mix(c,MOSS,m);}
  if(crev>0)c=api.mix(c,GREY,0.5*crev);
  return c;
}
const addM=(m,e,c)=>{m.vertexColor((x,y,z)=>stain(x,y,z,e,c));api.add(m,marbleM);};
const addA=(m,e)=>{m.vertexColor((x,y,z)=>stain(x,y,z,e,0));api.add(m,ashM);};
function ext(pts,dep){
  let a=0;
  for(let i=0;i<pts.length;i++){const p=pts[i],q=pts[(i+1)%pts.length];a+=p[0]*q[1]-q[0]*p[1];}
  if(a<0)pts=pts.slice().reverse();
  return api.extrude(pts,dep);
}
function slab(ax,ay,bx,by,off,h,zc,dep){
  return ext([[ax,ay+off],[bx,by+off],[bx,by+off+h],[ax,ay+off+h]],dep).translate(0,0,zc);
}
let goldAll=null;const addG=m=>{if(!goldAll)goldAll=m;else goldAll.merge(m);};
let leafAll=null;let balAll=null;
// ---------- stairs (built in chunks: extrude is limited to 512 points)
function stairMesh(sgn,xs,y0,rise,zc,dep){
  const X=s=>xs+sgn*s;
  const CH=33;
  let m=null;
  for(let i0=0;i0<N;i0+=CH){
    const i1=Math.min(N,i0+CH);
    const pts=[];
    if(i0===0)pts.push([X(0.03),0]);else pts.push([X(i0*d),Math.max(0,y0+i0*rise-SOFFIT)]);
    for(let i=i0;i<i1;i++){
      const s0=i*d,y=y0+i*rise;
      if(i>0)pts.push([X(s0+0.03),y-rise]);
      pts.push([X(s0+0.03),y-0.035]);
      pts.push([X(s0),y-0.012]);
      pts.push([X(s0+0.012),y]);
      pts.push([X(s0+d*0.6),y-0.008]);
    }
    pts.push([X(i1*d),y0+(i1-1)*rise]);
    // A flight is a slab 1.4 m deep carried on piers, not a wedge filled down to the ground (except low down, where it meets the quay).
    const soff=(i)=>Math.max(0,y0+i*rise-SOFFIT);
    pts.push([X(i1*d),soff(i1)]);
    const part=ext(pts,dep).translate(0,0,zc);
    if(!m)m=part;else m.merge(part);
  }
  const hz=dep/2;
  m.vertexColor((x,y,z)=>{
    const s=sgn*(x-xs);
    let f=(s/d)%1;if(f<0)f+=1;if(f>0.97)f=0;
    const edge=Math.min(1,(f<0.07?0.85:0.15)+0.5*Math.pow(Math.abs(z-zc)/hz,3));
    const crev=Math.abs(f-0.1228)<0.02?1:0;
    return stain(x,y,z,edge,crev);
  });
  return m;
}
api.add(stairMesh(1,-16,1.0,22.5/131,-2.4,4.2),marbleM);
api.add(stairMesh(-1,16,23.5,22/131,-7,5),marbleM);
// ---------- front wall: backing, ashlar blocks
addA(ext([[-16,0],[20,0],[20,23.2],[16,23.2],[-16,0.7]],0.22).translate(0,0,-0.29),0.1);
const niches=[-10,-6,-2,2,6,10,14,18];
const NRO=0.75,NRI=0.55,NHS=2.55,NYB=0.55,NTOP=NYB+NHS+NRO;
let blocks=null;
function addBlock(x0,x1,y0,y1){
  const w=x1-x0-0.014,h=y1-y0-0.014;
  if(w<0.15)return;
  const cx=(x0+x1)/2,cy=(y0+y1)/2;
  const m=api.box(w,h,0.2).translate(cx,cy,-0.1);
  const col=stain(cx,cy,0.3,0.05+0.3*api.rng(),0);
  m.vertexColor(()=>col);
  if(!blocks)blocks=m;else blocks.merge(m);
}
function clipBlock(a,b,y0,y1){
  let pcs=[[a,b]];
  if(y0<NTOP){
    for(const n of niches){
      const nw=[];
      for(const p of pcs){
        if(p[1]<=n-NRO||p[0]>=n+NRO){nw.push(p);}
        else{
          if(p[0]<n-NRO)nw.push([p[0],n-NRO]);
          if(p[1]>n+NRO)nw.push([n+NRO,p[1]]);
        }
      }
      pcs=nw;
    }
  }
  for(const p of pcs)addBlock(p[0],p[1],y0,y1);
}
for(let c=0;c<60;c++){
  const y0=0.5+c*0.45;
  const y1=Math.min(y0+0.45,23.2);
  if(y1-y0<0.2)break;
  if(y1+0.3<=1)continue;
  const xs=Math.max(-16,-16+(y1+0.3-1)/kA);
  let x=xs,first=true;
  while(x<19.95){
    let w=first?((c%2)?0.5+api.rng()*0.8:1.3+api.rng()*0.9):1.3+api.rng()*1.1;
    first=false;
    if(20-x-w<0.6)w=20-x;
    clipBlock(x,x+w,y0,y1);
    x+=w;
  }
}
if(blocks)api.add(blocks,ashM);
// plinth, bands, cornice
addM(api.roundedBox(36.2,0.55,0.34,0.04,1).translate(2,0.275,0),0.2,0);
addM(api.roundedBox(0.34,0.55,11.5,0.04,1).translate(20,0.275,-5.75),0.2,0);
addM(api.roundedBox(4,0.55,0.34,0.04,1).translate(18,0.275,-11.5),0.2,0);
for(const y of [6,12,18]){
  const xs=-16+(y+0.6-1)/kA;
  addM(api.roundedBox(20-xs,0.3,0.32,0.03,1).translate((xs+20)/2,y,0),0.25,0);
  addM(api.roundedBox(0.32,0.3,11.5,0.03,1).translate(20,y,-5.75),0.25,0);
  addM(api.roundedBox(4,0.3,0.32,0.03,1).translate(18,y,-11.5),0.25,0);
}
addM(api.roundedBox(0.34,0.55,7,0.04,1).translate(-20,0.275,-8),0.2,0);
addM(api.roundedBox(4,0.55,0.34,0.04,1).translate(-18,0.275,-4.5),0.2,0);
addM(api.roundedBox(4,0.55,0.34,0.04,1).translate(-18,0.275,-11.5),0.2,0);
for(let y=6;y<45;y+=6){
  addM(api.roundedBox(0.32,0.3,7,0.03,1).translate(-20,y,-8),0.25,0);
  addM(api.roundedBox(4,0.3,0.32,0.03,1).translate(-18,y,-4.5),0.25,0);
  addM(api.roundedBox(4,0.3,0.32,0.03,1).translate(-18,y,-11.5),0.25,0);
}
addM(slab(-16,lineA(-16),16,lineA(16),-0.3,0.3,-0.125,0.55),0.45,0);
addM(api.roundedBox(4.2,0.3,0.55,0.03,1).translate(18.1,23.35,-0.125),0.45,0);
// buttress piers
function pier(px,top){
  let y=0,j=0;
  while(y<top-0.01){
    const h=Math.min(3,top-y);
    const w=Math.max(0.7,1.8-0.14*j),pr=Math.max(0.2,0.62-0.07*j);
    addM(api.roundedBox(w,h,pr+0.15,0.04,1).translate(px,y+h/2,(pr-0.15)/2),0.2,0);
    y+=h;j++;
  }
}
for(const px of [-16,0,16])pier(px,lineA(px)-0.3);
// Piers under the upper flight: it reads as a viaduct climbing the cliff, with the rock and the falls seen between them.
for(const px of [-12,-6,0,6,12]){
  const top=lineB(px)-SOFFIT;
  addA(api.roundedBox(1.6,top,4.6,0.05,1).translate(px,top/2,-7),0.15);
  addM(api.roundedBox(2,0.35,5,0.04,1).translate(px,top-0.175,-7),0.3,0);
  addM(api.roundedBox(2.1,0.5,5.1,0.04,1).translate(px,0.25,-7),0.2,0);
}
// niches
function archPts(r,hs,n,rev){
  const p=[];
  for(let i=1;i<n;i++){const a=rev?Math.PI*i/n:Math.PI-Math.PI*i/n;p.push([r*Math.cos(a),hs+r*Math.sin(a)]);}
  return p;
}
const frame=[[-NRO,0],[-NRO,NHS]].concat(archPts(NRO,NHS,10,false),[[NRO,NHS],[NRO,0],[NRI,0],[NRI,NHS]],archPts(NRI,NHS,10,true),[[-NRI,NHS],[-NRI,0]]);
const inner=[[-NRI,0],[-NRI,NHS]].concat(archPts(NRI,NHS,10,false),[[NRI,NHS],[NRI,0]]);
for(const nx of niches){
  addM(ext(frame,0.28).translate(nx,NYB,-0.04),0.35,0);
  const back=ext(inner,0.02).translate(nx,NYB,-0.17);
  back.vertexColor((x,y,z)=>api.mix(stain(x,y,z,0.1,0.6),'#7d8288',0.4));
  api.add(back,marbleM);
  addM(api.roundedBox(0.42,0.5,0.42,0.03,1).translate(nx,NYB+0.25,-0.04),0.2,0);
  const s=0.9+api.rng()*0.25;
  addM(api.lathe([[0,0],[0.09,0],[0.1,0.05],[0.06,0.12],[0.14,0.3],[0.15,0.4],[0.1,0.5],[0.11,0.56],[0,0.56]],10).scale(s).translate(nx,NYB+0.5,-0.04),0.3,0);
}
// ---------- landings (solid towers)
addA(api.roundedBox(4,23.35,11.2,0.05,1).translate(18,11.675,-5.9),0.15);
addM(api.roundedBox(4.2,0.15,11.3,0.04,1).translate(18.1,23.425,-6.05),0.3,0);
addA(api.roundedBox(4,45.35,7,0.05,1).translate(-18,22.675,-8),0.15);
addM(api.roundedBox(4.2,0.15,7.4,0.04,1).translate(-18.1,45.425,-8),0.3,0);
// ---------- balustrades
const postSet={};
function post(px,pz,y){
  const key=px.toFixed(2)+'|'+pz.toFixed(2);
  if(postSet[key])return;postSet[key]=1;
  addM(api.roundedBox(0.34,1.2,0.34,0.02,1).translate(px,y+0.3,pz),0.15,0);
  addM(api.roundedBox(0.46,0.12,0.46,0.025,1).translate(px,y+0.96,pz),0.3,0);
}
const balProto=api.lathe([[0.045,0],[0.045,0.06],[0.028,0.13],[0.058,0.36],[0.028,0.6],[0.04,0.68],[0.04,0.76]],6);
function laurel(a,b){
  const Lx=b.x-a.x,Ly=b.y-a.y;
  const ang=Math.atan2(Ly,Lx)*180/Math.PI;
  const stem=slab(a.x+Lx*0.06,a.y+Ly*0.06,a.x+Lx*0.94,a.y+Ly*0.94,0.425,0.03,-0.04,0.03);
  addM(stem,0.4,0);
  for(let u=0.1;u<0.91;u+=0.05){
    const px=a.x+Lx*u,py=a.y+Ly*u+0.44;
    for(const sg of [1,-1]){
      const an=ang+sg*38,r=an*Math.PI/180;
      const lx=px+Math.cos(r)*0.12,ly=py+Math.sin(r)*0.12;
      const lf=api.sphere(1,0).scale(0.13,0.04,0.03).rotate(0,0,an).translate(lx,ly,-0.05);
      const col=stain(lx,ly,-0.05,0.5,0);
      lf.vertexColor(()=>col);
      if(!leafAll)leafAll=lf;else leafAll.merge(lf);
    }
  }
}
function run(x0,z0,x1,z1,yAt,solid){
  if(x1<x0||(x1===x0&&z1<z0)){let t=x0;x0=x1;x1=t;t=z0;z0=z1;z1=t;}
  const xrun=Math.abs(x1-x0)>=Math.abs(z1-z0);
  const L=xrun?Math.abs(x1-x0):Math.abs(z1-z0);
  const n=Math.max(1,Math.round(L/4));
  const P=[];
  for(let i=0;i<=n;i++){const t=i/n;const px=x0+(x1-x0)*t,pz=z0+(z1-z0)*t;P.push({x:px,z:pz,y:yAt(px,pz)});}
  for(const p of P)post(p.x,p.z,p.y);
  for(let i=0;i<n;i++){
    const a=P[i],b=P[i+1];
    if(xrun){
      const zc=a.z;
      if(solid){
        addM(slab(a.x,a.y,b.x,b.y,-0.15,1.03,zc,0.25),0.2,0);
        if(i%2===1)laurel(a,b);
      }else{
        addM(slab(a.x,a.y,b.x,b.y,-0.12,0.24,zc,0.26),0.2,0);
      }
      addM(slab(a.x,a.y,b.x,b.y,0.88,0.12,zc,0.38),0.3,0);
      const dx=b.x-a.x,dy=b.y-a.y;
      api.collider({kind:'box',halfExtents:[Math.hypot(dx,dy)/2,0.5,0.15],offset:[(a.x+b.x)/2,(a.y+b.y)/2+0.5,zc],rotation:[0,0,Math.atan2(dy,dx)*180/Math.PI]});
    }else{
      const len=Math.abs(b.z-a.z),mz=(a.z+b.z)/2;
      if(!solid){
        addM(api.roundedBox(0.26,0.24,len,0.03,1).translate(a.x,a.y,mz),0.2,0);
      }
      addM(api.roundedBox(0.38,0.12,len,0.03,1).translate(a.x,a.y+0.94,mz),0.3,0);
      api.collider({kind:'box',halfExtents:[0.15,0.5,len/2],offset:[a.x,a.y+0.5,mz]});
    }
    if(!solid){
      const Ls=xrun?Math.abs(b.x-a.x):Math.abs(b.z-a.z);
      const m=Math.max(2,Math.round(Ls/0.35));
      for(let j=1;j<m;j++){
        const t=j/m;
        const px=a.x+(b.x-a.x)*t,pz=a.z+(b.z-a.z)*t,py=a.y+(b.y-a.y)*t+0.12;
        const bm=balProto.clone().translate(px,py,pz);
        const col=stain(px,py,pz,0.12,0);
        bm.vertexColor(()=>col);
        if(!balAll)balAll=bm;else balAll.merge(bm);
      }
    }
  }
}
const F=(y)=>()=>y;
run(-16,-0.175,16,-0.175,lineA,true);
run(16,-0.175,19.84,-0.175,F(23.5),true);
run(-16,-4.66,16,-4.66,lineB,false);
run(-16,-4.66,-19.84,-4.66,F(45.5),false);
run(-19.84,-4.66,-19.84,-11.34,F(45.5),false);
run(-19.84,-11.34,-16.16,-11.34,F(45.5),false);
run(-16.16,-11.34,-16.16,-9.34,F(45.5),false);
run(-16,-9.34,16,-9.34,lineB,false);
run(16.16,-9.34,16.16,-11.34,F(23.5),false);
run(16.16,-11.34,19.84,-11.34,F(23.5),false);
run(19.84,-11.34,19.84,-0.175,F(23.5),false);
if(balAll)api.add(balAll,marbleM);
if(leafAll)api.add(leafAll,marbleM);
// ---------- braziers
if(params.braziers!==false){
  const prof=[[0,0],[0.13,0],[0.15,0.05],[0.06,0.12],[0.05,0.25],[0.1,0.3],[0.24,0.4],[0.34,0.52],[0.35,0.62],[0.31,0.62],[0.22,0.5],[0,0.44]];
  for(const bx of [-16,-8,0,8,16]){
    const by=lineA(bx)+1.02;
    api.add(api.lathe(prof,14).translate(bx,by,-0.175),bronzeM);
    api.add(api.cone(0.2,0.55,8).translate(bx,by+0.775,-0.175),flameM);
    api.add(api.cone(0.11,0.8,6).translate(bx+0.04,by+0.9,-0.175),flameM);
  }
}
// ---------- banners
if(params.banners!==false){
  for(const bx of [-12,-4,4,12]){
    const top=lineA(bx)-0.6;
    const hb=Math.min(4,top-0.7);
    const yc=top-hb/2;
    const cloth=api.plane(1.4,hb,5,10).rotate(90,0,0).translate(bx,yc,0.2).warp((px,py,pz)=>[px,py,pz+0.015*Math.sin(py*2.3+px*2.0)]);
    api.add(cloth,bannerM);
    addG(api.roundedBox(0.07,hb,0.02,0.005,1).translate(bx-0.665,yc,0.222));
    addG(api.roundedBox(0.07,hb,0.02,0.005,1).translate(bx+0.665,yc,0.222));
    addG(api.roundedBox(1.4,0.08,0.02,0.005,1).translate(bx,top-hb+0.04,0.222));
    addG(api.roundedBox(0.025,hb-0.3,0.02,0.004,1).translate(bx-0.52,yc,0.222));
    addG(api.roundedBox(0.025,hb-0.3,0.02,0.004,1).translate(bx+0.52,yc,0.222));
    addG(api.roundedBox(1.04,0.025,0.02,0.004,1).translate(bx,top-hb+0.16,0.222));
    addG(api.roundedBox(1.04,0.025,0.02,0.004,1).translate(bx,top-0.14,0.222));
    addG(api.roundedBox(1.62,0.07,0.07,0.02,1).translate(bx,top+0.03,0.22));
    addG(ext([[0,0.3],[0.22,0],[0,-0.3],[-0.22,0]],0.02).translate(bx,yc+hb*0.12,0.226));
    for(const sx of [-0.6,0.6]){
      addG(api.roundedBox(0.04,0.04,0.2,0.01,1).translate(bx+sx,top+0.03,0.1));
      addG(api.sphere(0.035,1).translate(bx+sx,top+0.03,0.0));
    }
    for(let t=0;t<5;t++)addG(api.roundedBox(0.04,0.14,0.02,0.005,1).translate(bx-0.5+t*0.25,top-hb-0.03,0.222));
  }
}
if(goldAll)api.add(goldAll,goldM);
// ---------- colliders
for(let k=0;k<8;k++){
  const xa=-16+4*k,xb=xa+4;
  api.collider({kind:'hull',offset:[0,0,0],points:[xa,0,-4.5,xa,0,0,xb,0,-4.5,xb,0,0,xa,lineA(xa),-4.5,xa,lineA(xa),0,xb,lineA(xb),-4.5,xb,lineA(xb),0]});
  api.collider({kind:'hull',offset:[0,0,0],points:[xa,0,-9.5,xa,0,-4.5,xb,0,-9.5,xb,0,-4.5,xa,lineB(xa),-9.5,xa,lineB(xa),-4.5,xb,lineB(xb),-9.5,xb,lineB(xb),-4.5]});
}
api.collider({kind:'box',halfExtents:[2,11.75,5.75],offset:[18,11.75,-5.75]});
api.collider({kind:'box',halfExtents:[2,22.75,3.5],offset:[-18,22.75,-8]});
return api.build();

marble-house.source:
// Classical hillside house or treasury: ashlar marble walls on a rubble footing that reaches down the slope, a pedimented
// porch of fluted columns on the front, low-pitched pale terracotta roof with a gilded acroterion; variant 1 adds a
// set-back upper storey with its own small pediment, variant 2 is a colonnaded stoa front.
const w = params.width, d = params.depth, fl = Math.max(1, Math.round(params.floors)), v = Math.round(params.variant);
const foot = params.footing;
const MARBLE = { finish: 'marble', color: params.wallColor, roughness: 0.45,
  surface: { layers: [{ kind: 'grime', color: '#8a7b5a', amount: 0.22, mask: { down: 0.5 } }, { kind: 'streaks', color: '#a39274', amount: 0.2, scale: 1 }] } };
const STONE = { finish: 'stone', color: '#b9ab8e', roughness: 0.9 };
const ROOF = { finish: 'roof-tile', color: params.roofColor, roughness: 0.65 };
const GOLD = { preset: 'gold', color: '#e3b856', roughness: 0.3, metalness: 1 };
const DARK = { color: '#3a3128', roughness: 0.9 };
let mar = null, stone = null, roof = null, gold = null, dark = null;
const m = (acc, mesh) => (acc === null ? mesh : acc.merge(mesh));
const RB = (a, b, c, r) => api.roundedBox(a, b, c, r, 1);
const fh = 3.6, H0 = fl * fh;
stone = m(stone, RB(w + 0.6, foot + 0.4, d + 0.6, 0.08).translate(0, (0.4 - foot) / 2, 0));
mar = m(mar, RB(w + 0.3, 0.25, d + 0.3, 0.04).translate(0, 0.52, 0));
const colT = (r, h) => {
  const c = api.lathe([[r, 0], [r, 0.12], [r * 0.95, 0.14], [r * 0.82, h - 0.32], [r * 1.25, h - 0.18], [r * 1.25, h - 0.06], [r * 1.3, h - 0.06], [r * 1.3, h], [0, h]], 12);
  return c;
};
const gable = (gw, y, z, depth, rise) => {
  const tri = api.extrude([[-gw / 2, 0], [gw / 2, 0], [0, rise]], depth);
  return tri.translate(0, y, z);
};
const building = (bw, bd, y, z, porch, h) => {
  // cella walls with a string course and cornice
  mar = m(mar, RB(bw, h, bd, 0.05).translate(0, y + h / 2, z));
  mar = m(mar, RB(bw + 0.25, 0.35, bd + 0.25, 0.04).translate(0, y + h + 0.17, z));
  mar = m(mar, RB(bw + 0.08, 0.14, bd + 0.08, 0.02).translate(0, y + h * 0.45, z));
  const rise = bw * 0.16;
  // low gabled roof running front to back, pediment faces on the front and back
  const half = bw / 2 + 0.35, L = bd + (porch ? 3.2 : 0.4);
  const zc = z + (porch ? 1.4 : 0);
  for (const sx of [-1, 1]) {
    const len = Math.hypot(half, rise);
    roof = m(roof, api.box(len, 0.18, L).rotate(0, 0, -sx * Math.atan2(rise, half) * 180 / Math.PI).translate(sx * half / 2, y + h + 0.36 + rise / 2, zc));
  }
  mar = m(mar, gable(bw + 0.5, y + h + 0.34, zc + L / 2 - 0.2, 0.3, rise));
  mar = m(mar, gable(bw + 0.5, y + h + 0.34, zc - L / 2 + 0.2, 0.3, rise));
  gold = m(gold, api.sphere(0.28, 1).scale(1, 1.4, 0.4).translate(0, y + h + 0.4 + rise + 0.25, zc + L / 2 - 0.2));
  // door and windows on the front wall
  dark = m(dark, api.box(1.2, 2.4, 0.1).translate(0, y + 1.2, z + bd / 2 + 0.02));
  gold = m(gold, api.box(1.45, 0.12, 0.08).translate(0, y + 2.48, z + bd / 2 + 0.05));
  for (const sx of [-1, 1]) {
    if (bw > 6) dark = m(dark, api.box(0.7, 1.3, 0.1).translate(sx * bw * 0.3, y + h * 0.62, z + bd / 2 + 0.02));
    dark = m(dark, api.box(0.1, 1.1, 0.6).translate(sx * (bw / 2 + 0.02), y + h * 0.62, z - bd * 0.15));
  }
  if (porch) {
    const n = v === 2 ? Math.max(4, Math.round(bw / 1.6)) : 4;
    const r = 0.26;
    for (let i = 0; i < n; i++) {
      const cx = -bw / 2 + 0.4 + i * (bw - 0.8) / (n - 1);
      mar = m(mar, colT(r, h).translate(cx, y, z + bd / 2 + 2.6));
    }
    mar = m(mar, RB(bw + 0.25, 0.6, 3.2, 0.03).translate(0, y + h + 0.0, z + bd / 2 + 1.5));
    mar = m(mar, RB(bw + 0.3, 0.25, 3.4, 0.03).translate(0, y - 0.05, z + bd / 2 + 1.5));
  }
};
building(w, d, 0.62, 0, true, H0);
if (v === 1) {
  const uw = w * 0.6, ud = d * 0.55;
  building(uw, ud, 0.62 + H0 + 0.4, -(d - ud) / 2, false, 3.0);
}
api.add(mar, MARBLE);
api.add(stone, STONE);
api.add(roof, ROOF);
api.add(gold, GOLD);
api.add(dark, DARK);
api.collider({ kind: 'box', halfExtents: [w / 2, (H0 + foot) / 2, d / 2], offset: [0, (H0 - foot) / 2, 0] });
return api.build({ recenter: false });

marble-temple-hexastyle.source:
const W = params.width, Ln = params.length, H = params.height;
const n = Math.max(4, Math.min(8, Math.round(params.columns)));
const m = 2 * n - 1;
const ivory = params.color, honey = params.honey;
const MB = { finish: 'marble', color: '#ffffff', roughness: 0.35 };
const RT = { finish: 'roof-tile', color: params.roofColor, roughness: 0.6 };
const y0 = 0.9;

const vc = (mesh, o) => {
  o = o || {};
  mesh.vertexColor((x, y, z) => {
    const v = 0.5 + 0.5 * api.noise3(x * 3.1, y * 0.22, z * 3.1);
    const w = api.noise3(x * 8.0 + 11, y * 0.5, z * 8.0);
    const vein = Math.max(0, 1 - Math.abs(w) * 7);
    let c = api.mix(ivory, '#bfae8c', Math.min(0.5, 0.10 * v + 0.22 * vein));
    const s = 0.5 + 0.5 * api.noise3(x * 5 + 3, y * 1.2, z * 5);
    let st = 0.26 * Math.exp(-Math.max(0, y - y0) / 0.6) * (0.55 + 0.45 * s);
    if (o.hs) {
      const dy = (y - y0) / o.hs * 4;
      const k = Math.round(dy);
      if (k >= 1 && k <= 3 && Math.abs(dy - k) < 0.03) st = Math.max(st, 0.16 * s);
    }
    c = api.mix(c, honey, Math.min(0.45, st));
    if (o.dark) c = api.mix(c, '#7d6c4e', o.dark);
    return c;
  });
  return mesh;
};
const ext = (shape, depth) => {
  const e = api.extrude(shape, depth);
  const b = e.bounds();
  return e.translate(-(b.min[0] + b.max[0]) / 2, -b.min[1], -(b.min[2] + b.max[2]) / 2);
};
const RB = (w, h, d, r) => api.roundedBox(w, h, d, r === undefined ? 0.02 : r, 1);
let body = null;
let gold = null;
const gput = (mesh) => { if (gold === null) gold = mesh; else gold.merge(mesh); };
let tymp = null;
const put = (mesh) => { if (body === null) body = mesh; else body.merge(mesh); };

// ---- crepidoma: three steps of 0.3 m
for (let i = 0; i < 3; i++) {
  const ins = 0.6 * i;
  const sw = W - 2 * ins, sl = Ln - 2 * ins;
  put(RB(sw, 0.3, sl, 0.03).translate(0, 0.15 + 0.3 * i, 0));
  api.collider({ kind: 'box', halfExtents: [sw / 2, 0.15, sl / 2], offset: [0, 0.15 + 0.3 * i, 0] });
}
const Ws = W - 1.2, Ls = Ln - 1.2;
const cx = Ws / 2 - 1.3, cz = Ls / 2 - 1.3;

// ---- columns
const spx = 2 * cx / (n - 1), spz = 2 * cz / (m - 1);
const r = Math.min(H * 0.085, Math.min(spx, spz) * 0.3);
const rt = r * 0.78;
const ech = 0.42, aba = 0.35;
const hs = H - ech - aba;
const prof = [];
for (let i = 0; i <= 4; i++) {
  const t = i / 4;
  prof.push([r * (1 - 0.22 * t) + 0.035 * r * Math.sin(Math.PI * t), hs * t]);
}
const colTpl = api.lathe(prof, 60).warp((x, y, z) => {
  const a = Math.abs(Math.sin(10 * Math.atan2(z, x)));
  const f = 1 - 0.075 * a;
  return [x * f, y, z * f];
});
const echM = api.lathe([[0, 0], [rt, 0], [rt * 1.06, 0.05], [rt * 1.06, 0.1], [rt * 1.12, 0.16], [rt * 1.25, 0.3], [rt * 1.32, ech], [0, ech]], 16).translate(0, hs, 0);
const abM = RB(rt * 2.8, aba, rt * 2.8, 0.02).translate(0, hs + ech + aba / 2, 0);
colTpl.merge(echM);
colTpl.merge(abM);

const colx = [], colz = [];
for (let i = 0; i < n; i++) colx.push(-cx + i * 2 * cx / (n - 1));
for (let j = 0; j < m; j++) colz.push(-cz + j * 2 * cz / (m - 1));
const cols = [];
for (let i = 0; i < n; i++) { cols.push([colx[i], -cz]); cols.push([colx[i], cz]); }
for (let j = 1; j < m - 1; j++) { cols.push([-cx, colz[j]]); cols.push([cx, colz[j]]); }
for (const c of cols) {
  const cm = colTpl.clone().translate(c[0], y0, c[1]);
  vc(cm, { hs: hs });
  api.add(cm, MB);
  api.collider({ kind: 'cylinder', halfHeight: H / 2, radius: r * 0.97, offset: [c[0], y0 + H / 2, c[1]] });
}

// ---- entablature
const A = 1.4 * rt + 0.04;
const ah = 0.095 * H, fh = 0.1 * H;
const yA = y0 + H, yF = yA + ah, yC = yF + fh;
const ax = cx + A, az = cz + A, ta = 0.9;
for (const sg of [1, -1]) {
  put(RB(2 * ax, ah, ta).translate(0, yA + ah / 2, sg * (az - ta / 2)));
  put(RB(ta, ah, 2 * (az - ta)).translate(sg * (ax - ta / 2), yA + ah / 2, 0));
  // taenia
  gput(RB(2 * (ax + 0.05), 0.1, 0.2, 0.01).translate(0, yF - 0.05, sg * (az - 0.05)));
  gput(RB(0.2, 0.1, 2 * (az + 0.05 - 0.2), 0.01).translate(sg * (ax - 0.05), yF - 0.05, 0));
}
const fx = ax - 0.05, fz = az - 0.05, tf = 0.7;
for (const sg of [1, -1]) {
  put(RB(2 * fx, fh, tf, 0.01).translate(0, yF + fh / 2, sg * (fz - tf / 2)));
  put(RB(tf, fh, 2 * (fz - tf), 0.01).translate(sg * (fx - tf / 2), yF + fh / 2, 0));
}
// triglyphs: over each column and mid-bay
const txs = [], tzs = [];
for (let i = 0; i < n; i++) { txs.push(colx[i]); if (i < n - 1) txs.push((colx[i] + colx[i + 1]) / 2); }
for (let j = 0; j < m; j++) { tzs.push(colz[j]); if (j < m - 1) tzs.push((colz[j] + colz[j + 1]) / 2); }
for (const sg of [1, -1]) {
  for (const xp of txs) for (let k = -1; k <= 1; k++) put(api.box(0.14, fh, 0.09).translate(xp + k * 0.205, yF + fh / 2, sg * (fz + 0.025)));
  for (const zp of tzs) for (let k = -1; k <= 1; k++) put(api.box(0.09, fh, 0.14).translate(sg * (fx + 0.025), yF + fh / 2, zp + k * 0.205));
}

// ---- cornice: bed band with dentils, corona, cap
const rx0 = ax + 0.25, rz0 = az + 0.25;
const rx1 = ax + 0.5, rz1 = az + 0.5;
const rx2 = ax + 0.4, rz2 = az + 0.4;
put(RB(2 * rx0, 0.12, 2 * rz0, 0.01).translate(0, yC + 0.06, 0));
put(RB(2 * rx1, 0.3, 2 * rz1, 0.02).translate(0, yC + 0.27, 0));
put(RB(2 * rx2, 0.15, 2 * rz2, 0.02).translate(0, yC + 0.495, 0));
for (const sg of [1, -1]) {
  for (let x = -rx0 + 0.25; x <= rx0 - 0.25; x += 0.34) put(api.box(0.18, 0.12, 0.1).translate(x, yC + 0.06, sg * (rz0 + 0.045)));
  for (let z = -rz0 + 0.25; z <= rz0 - 0.25; z += 0.34) put(api.box(0.1, 0.12, 0.18).translate(sg * (rx0 + 0.045), yC + 0.06, z));
}
const yb = yC + 0.42, yst = yC + 0.57;

// ---- pediments
const hw = rx2, zf = rz1;
const rise = 0.2 * hw;
const alpha = Math.atan2(rise, hw), ad = alpha * 180 / Math.PI;
const slope = rise / hw;
const Lr = Math.hypot(hw, rise) + 0.4;
const v0 = 0.45 / Math.cos(alpha);
const roofTop = (yst - yb) + rise + v0;
const pal = [[-0.35, 0], [-0.5, 0.35], [-0.62, 0.8], [-0.42, 1.05], [-0.3, 1.45], [-0.12, 1.3], [0, 1.7], [0.12, 1.3], [0.3, 1.45], [0.42, 1.05], [0.62, 0.8], [0.5, 0.35], [0.35, 0]];
let figs = null;
const fput = (mesh) => { if (figs === null) figs = mesh; else figs.merge(mesh); };
const fs = rise / 1.89;
const specs = [[0, 'stand', 1.45, 2], [-1.9, 'stand', 1.15, 1], [1.9, 'stand', 1.15, 1], [-3.5, 'sit', 0.85, 0], [3.5, 'sit', 0.85, 0], [-5.3, 'lie', 1.0, 0], [5.3, 'lie', 1.0, 0]];
for (const sg of [1, -1]) {
  { const tm = ext([[-hw, 0], [hw, 0], [0, rise]], 0.4).translate(0, yst, sg * (zf - 0.5)); if (tymp === null) tymp = tm; else tymp.merge(tm); }
  put(RB(Lr, 0.45, 0.6, 0.03).rotate(0, 0, ad).translate(-hw / 2 - 0.225 * Math.sin(alpha), yst + rise / 2 + 0.225 * Math.cos(alpha), sg * (zf - 0.3)));
  put(RB(Lr, 0.45, 0.6, 0.03).rotate(0, 0, -ad).translate(hw / 2 + 0.225 * Math.sin(alpha), yst + rise / 2 + 0.225 * Math.cos(alpha), sg * (zf - 0.3)));
  // acroteria
  put(RB(1.0, 0.22, 0.5, 0.02).translate(0, yb + roofTop - 0.1, sg * (zf - 0.4)));
  gput(ext(pal, 0.35).scale(1.3).translate(0, yb + roofTop - 0.02, sg * (zf - 0.4)));
  for (const sx of [-1, 1]) {
    gput(ext(pal, 0.35).scale(0.9).translate(sx * (hw - 0.35), yst - 0.02, sg * (zf - 0.4)));
  }
  // relief figures
  const zc = sg * (zf - 0.3 + 0.06);
  const yfig = yst + 0.1;
  for (const sp of specs) {
    const fxp = sp[0], kind = sp[1], g = sp[2] * fs;
    const dir = fxp > 0 ? -1 : (fxp < 0 ? 1 : 1);
    const part = (mesh, lx, ly, rz) => {
      mesh.rotate(0, 0, rz || 0).translate(lx, ly, 0).scale(1, 1, 0.8).translate(fxp, yfig, zc);
      fput(mesh);
    };
    if (kind === 'stand') {
      part(api.capsule(0.15 * g, 0.8 * g), 0, 0.4 * g, 0);
      part(api.sphere(0.11 * g, 1), 0, 0.88 * g, 0);
      part(api.capsule(0.045 * g, 0.45 * g), 0.21 * g, 0.55 * g, -25);
      if (sp[3] === 2) part(api.capsule(0.045 * g, 0.45 * g), -0.21 * g, 0.55 * g, 25);
    } else if (kind === 'sit') {
      part(api.capsule(0.14 * g, 0.65 * g), 0, 0.62 * g, 0);
      part(api.sphere(0.1 * g, 1), 0, 1.02 * g, 0);
      part(api.capsule(0.09 * g, 0.55 * g), dir * 0.22 * g, 0.22 * g, 90);
      part(api.capsule(0.07 * g, 0.4 * g), dir * 0.5 * g, 0.12 * g, 0);
    } else {
      part(api.capsule(0.12 * g, 1.1 * g), 0, 0.18 * g, 90);
      part(api.sphere(0.1 * g, 1), dir * 0.64 * g, 0.3 * g, 0);
      part(api.capsule(0.07 * g, 0.5 * g), -dir * 0.3 * g, 0.4 * g, dir * 35);
    }
  }
}

// ---- roof
const hwr = rx1;
const ye = roofTop - slope * hwr;
const zr = zf - 0.55;
const roofM = ext([[-hwr, 0], [hwr, 0], [hwr, ye], [0, roofTop], [-hwr, ye]], 2 * zr).translate(0, yb, 0);
roofM.merge(RB(0.7, 0.4, 2 * zr - 0.2, 0.05).translate(0, yb + roofTop + 0.05, 0));
const a2 = Math.atan2(roofTop - ye, hwr), a2d = a2 * 180 / Math.PI;
const Ls2 = Math.hypot(hwr, roofTop - ye);
const nrib = Math.floor((2 * zr - 1.2) / 1.6);
for (let i = 0; i <= nrib; i++) {
  const zz = -zr + 0.6 + i * (2 * zr - 1.2) / nrib;
  roofM.merge(api.box(Ls2, 0.07, 0.14).rotate(0, 0, a2d).translate(-hwr / 2 - 0.035 * Math.sin(a2), yb + (ye + roofTop) / 2 + 0.035 * Math.cos(a2), zz));
  roofM.merge(api.box(Ls2, 0.07, 0.14).rotate(0, 0, -a2d).translate(hwr / 2 + 0.035 * Math.sin(a2), yb + (ye + roofTop) / 2 + 0.035 * Math.cos(a2), zz));
}
api.add(roofM, RT);

// ---- cella
const cxc = cx - 2.3, czc = cz - 3.6, tw = 0.6;
const hc = yC - y0;
for (const sg of [1, -1]) put(RB(tw, hc, 2 * (czc - tw)).translate(sg * (cxc - tw / 2), y0 + hc / 2, 0));
put(RB(2 * cxc, hc, tw).translate(0, y0 + hc / 2, -(czc - tw / 2)));
const dw = Math.min(2.8, cxc * 0.5), dh = Math.min(0.56 * H, hc - 1.5);
const zw = czc - tw / 2;
const sideW = cxc - dw / 2;
put(RB(sideW, hc, tw).translate(-(dw / 2 + sideW / 2), y0 + hc / 2, zw));
put(RB(sideW, hc, tw).translate(dw / 2 + sideW / 2, y0 + hc / 2, zw));
put(RB(dw, hc - dh, tw).translate(0, y0 + dh + (hc - dh) / 2, zw));
for (const sx of [-1, 1]) put(RB(0.3, dh, 0.8).translate(sx * (dw / 2 + 0.15), y0 + dh / 2, zw));
put(RB(dw + 1.0, 0.4, 0.8).translate(0, y0 + dh + 0.2, zw));
put(RB(dw + 1.4, 0.2, 1.0).translate(0, y0 + dh + 0.5, zw));
// antae at both ends
for (const sg of [1, -1]) for (const sx of [-1, 1]) {
  const px = sx * (cxc - 0.45), pz = sg * (czc + 0.2);
  put(RB(0.9, hc, 0.55).translate(px, y0 + hc / 2, pz));
  put(RB(1.1, 0.3, 0.7).translate(px, y0 + hc - 0.15, pz));
  put(RB(1.1, 0.25, 0.7).translate(px, y0 + 0.125, pz));
}
// windows
const archShape = (w, h) => {
  const pts = [[-w / 2, 0], [w / 2, 0]];
  const rr = w / 2, cy = h - rr;
  for (let i = 0; i <= 8; i++) { const a = Math.PI * i / 8; pts.push([Math.cos(a) * rr, cy + Math.sin(a) * rr]); }
  return pts;
};
let glassM = null;
const wbase = y0 + 3.8;
for (const sx of [-1, 1]) for (const zz of [-0.55, 0, 0.55]) {
  const zs = zz * czc;
  put(ext(archShape(1.3, 2.65), 0.2).rotate(0, 90, 0).translate(sx * cxc, wbase - 0.1, zs));
  put(RB(0.35, 0.12, 1.6, 0.02).translate(sx * (cxc + 0.12), wbase - 0.16, zs));
  const pn = ext(archShape(1.0, 2.4), 0.3).rotate(0, 90, 0).translate(sx * (cxc + 0.03), wbase, zs);
  if (glassM === null) glassM = pn; else glassM.merge(pn);
}
api.add(glassM, { preset: 'glass', color: '#33414f', opacity: 0.92, roughness: 0.15 });
// door leaves
let doorM = null, handleM = null;
const leafW = dw / 2 - 0.03, lz = czc - 0.45;
for (const sx of [-1, 1]) {
  const leaf = RB(leafW, dh - 0.05, 0.12, 0.01).translate(sx * dw / 4, y0 + (dh - 0.05) / 2, lz);
  if (doorM === null) doorM = leaf; else doorM.merge(leaf);
  doorM.merge(RB(leafW * 0.7, dh * 0.3, 0.05, 0.01).translate(sx * dw / 4, y0 + dh * 0.27, lz + 0.07));
  doorM.merge(RB(leafW * 0.7, dh * 0.3, 0.05, 0.01).translate(sx * dw / 4, y0 + dh * 0.7, lz + 0.07));
  const hd = api.torus(0.09, 0.018).translate(sx * 0.18, y0 + dh * 0.45, lz + 0.1);
  if (handleM === null) handleM = hd; else handleM.merge(hd);
}
api.add(doorM, { finish: 'oak', color: '#5e4126', roughness: 0.6 });
api.add(handleM, { finish: 'black-metal', color: '#2a2a2a' });
api.collider({ kind: 'box', halfExtents: [cxc, hc / 2, czc], offset: [0, y0 + hc / 2, 0] });

// ---- finish
vc(body, {});
api.add(body, MB);
api.add(figs, { preset: 'gold', color: '#e3b856', roughness: 0.28, metalness: 1 });
if (gold) api.add(gold, { preset: 'gold', color: '#e3b856', roughness: 0.28, metalness: 1 });
if (tymp) api.add(tymp, { finish: 'plaster', color: '#2d4f86', roughness: 0.7 });
return api.build();

sanctuary-massif.source:
// Sanctuary massif: one organic stepped limestone hill around the lagoon. Terraces follow meandering contours,
// broken limestone risers with strata between dry olive-ochre treads; the temple plateau stays level at y 45.
const S = 7.5, X0 = 170, ZN = -190, ZS = 50;
const hash = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7) * 43758.5453; return s - Math.floor(s); };
const vn = (x, z) => {
  const i = Math.floor(x), j = Math.floor(z), fx = x - i, fz = z - j;
  const ux = fx * fx * (3 - 2 * fx), uz = fz * fz * (3 - 2 * fz);
  const a = hash(i, j), b = hash(i + 1, j), c = hash(i, j + 1), d = hash(i + 1, j + 1);
  return (a + (b - a) * ux + (c - a) * uz + (a - b - c + d) * ux * uz) * 2 - 1;
};
const fbm = (x, z) => vn(x, z) * 0.6 + vn(x * 2.03 + 5.2, z * 2.03 + 1.3) * 0.3 + vn(x * 4.1 + 9.1, z * 4.1 + 3.7) * 0.1;
const ss = (a, b, v) => { const t = Math.max(0, Math.min(1, (v - a) / (b - a))); return t * t * (3 - 2 * t); };
const hill = (z) => 36 * ss(-96, -180, z);
const contour = (x, z) => {
  const ax = Math.abs(x);
  if (ax < 34 && z < -31 && z > -90) return 45;
  if (ax < 40 && z >= -31) return -1;
  const back = Math.min((30 - z) / 70, 1.3);
  let cs = 14 + 31 * back + 0.15 * Math.max(0, ax - 50) + hill(z) + 7 * fbm(x / 38 + 3, z / 38);
  cs *= ss(56, 30, z + 4 * fbm(x / 12, 9));
  const edge = ss(39.5, 50, ax + 3 * fbm(x / 9 + 1, z / 9));
  let c = z < -31 ? cs : cs * edge;
  if (ax < 46 && z < -31) c = Math.max(c, 45 + hill(z));
  if (c > 70) c = 70 + 0.3 * (c - 70);
  return c;
};
const H = (x, z) => {
  const c = contour(x, z);
  if (c === 45 && Math.abs(x) < 34 && z > -90 && z < -31) return 45;
  if (c < 0.5) return -0.4;
  const Sl = S * (1 + 0.3 * fbm(x / 70 + 2, z / 70 + 5));
  const u = c / Sl + 0.3 * fbm(x / 16 + 7, z / 16 - 2);
  const k = Math.floor(u), f = u - k;
